head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldstf10099";
scwin.gAcptNo = undefined;
scwin.gViewerStat = undefined;
scwin.gAskScrenID = undefined;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldstf10099.onpageload' });
    }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getParam
 * @description get Param 처리
 * @returns {void}
 * @hidden N
 */
scwin.getParam = function () {
    const pvd = scwin.getProvider();
    const Temp0 = pvd.split("&")[0];
    scwin.gAcptNo = Temp0.split("=")[1];
    scwin.gViewerStat = "P";
    gAccssAuthTpCd = "01";
    scwin.gAskScrenID = "ULDSTF10099.gfm";
};

/**
 * @method
 * @name getProvider
 * @description get Provider 처리
 * @returns {void}
 * @hidden N
 */
scwin.getProvider = function () {
    // TODO Stage2: 공급사 pcc 의존(저장소 pcc/fil 에 없음 · 반입 또는 치환 판단) — $c.frame.srcUrl
    const url = $c.frame.srcUrl;
    const arr = url.split("?")[1];
    return (arr.length >= 1 ? arr : undefined);
};

/**
 * @method
 * @name closeWin
 * @description close Win 처리
 * @returns {void}
 * @hidden N
 */
scwin.closeWin = function () {
    // TODO Stage2: 공급사 pcc 의존(저장소 pcc/fil 에 없음 · 반입 또는 치환 판단) — $c.frame.CloseFrame
    $c.win.closePopup();
};
